mapper.select:
SELECT DISTINCT M.MENU_ID , M.MENU_NAME , M.MENU_TYPE , M.PARENT_MENU_ID , M.SORT_ORDER , M.DATA_STATUS , M.CREATED_BY , M.CREATED_AT , M.UPDATED_BY , M.UPDATED_AT FROM TB_MENU M
INNER JOIN TB_MENU_AUTHORITY MA ON M.MENU_ID = MA.MENU_ID
WHERE TRUE
AND MA.AUTHORITY_CODE IN
#{authority}
AND M.MENU_TYPE = #{menuType}
AND M.DATA_STATUS = #{dataStatus}
AND M.DATA_STATUS != 'DELETED' ORDER BY M.SORT_ORDER

mapper.update:
UPDATE TB_MENU
MENU_NAME = #{menuName}, DATA_STATUS = #{dataStatus}, UPDATED_BY = #{author},
WHERE MENU_ID = #{targetMenuId}
